(24861, 'Acts 19:17', 'Acts', 19, 17, 'کله چې د افسیس ټول اوسېدونکي یهودیان او یونانیان د دې پېښې څخه خبر شول، نو په هغوی ټولو باندې وېره راغله او د څښتن عیسی نوم نور هم سرلوړی شو.', 'کله چې د افسیس تول اوسېدونکی یهودیان او یونانیان د دې پېشې چخه خبر شول، نو په هغوی تولو باندې وېره راغله او د چشتن عیسی نوم نور هم سرلوری شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(24862, 'Acts 19:18', 'Acts', 19, 18, 'ډېرو خلکو چې ایمان یې راوړی ؤ، راغلل او دا اقرار یې وکړ چې هغوی جادوګري کوله.', 'دېرو خلکو چې ایمان یې راوری و، راغلل او دا اقرار یې وکر چې هغوی جادوګری کوله.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24863, 'Acts 19:19', 'Acts', 19, 19, 'ډېرو جادوګرانو خپل د جادوګرۍ کتابونه راټول کړل او د خلکو په مخکې یې وسوځول. کله چې هغوی د کتابونو قیمتونه حساب کړل، نو د هغو بیه پنځوس زره د سپینو زرو سکې شوې.', 'دېرو جادوګرانو خپل د جادوګری کتابونه راتول کرل او د خلکو په مخکې یې وسوجول. کله چې هغوی د کتابونو قیمتونه حساب کرل، نو د هغو بیه پنجوس زره د سپینو زرو سکې شوې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(24864, 'Acts 19:20', 'Acts', 19, 20, 'په دې ډول د څښتن عیسی پیغام خپرېده او په خلکو یې ډېره اغېزه کوله. په افسیس کې شور او غوغا', 'په دې دول د چشتن عیسی پیغام خپرېده او په خلکو یې دېره اغېزه کوله. په افسیس کې شور او غوغا', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24865, 'Acts 19:21', 'Acts', 19, 21, 'د دې ټولو پېښو نه وروسته پولوس د روح القدس په لارښوونه پرېکړه وکړه چې مقدونیې او جنوبي یونان ته سفر وکړي او وروسته بیا اورشلیم ته لاړ شي. هغه وویل: «هغه ځای ته د تللو نه وروسته باید د روم ښار هم ووینم.»', 'د دې تولو پېشو نه وروسته پولوس د روح القدس په لارشوونه پرېکره وکره چې مقدونیې او جنوبی یونان ته سفر وکری او وروسته بیا اورشلیم ته لار شی. هغه وویل: «هغه جای ته د تللو نه وروسته باید د روم شار هم ووینم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(24866, 'Acts 19:22', 'Acts', 19, 22, 'هغه خپل دوه ملګري یعنې تیموتاوس او اراستوس مقدونیې ته ولېږل او په خپله د یو څه وخت دپاره د اسیا په ولایت کې پاتې شو.', 'هغه خپل دوه ملګری یعنې تیموتاوس او اراستوس مقدونیې ته ولېزل او په خپله د یو چه وخت دپاره د اسیا په ولایت کې پاتې شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24867, 'Acts 19:23', 'Acts', 19, 23, 'په دې وخت کې د څښتن عیسی د لارې له امله سخت شور او غوغا پیدا شوه.', 'په دې وخت کې د چشتن عیسی د لارې له امله سخت شور او غوغا پیدا شوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24868, 'Acts 19:24', 'Acts', 19, 24, 'هلته د دیمیتریوس په نوم یو زرګر ؤ چې د ارتیمیسې د بت د عبادت ځای د سپینو زرو نمونې به یې جوړولې او په دې ډول یې د کسبګرو دپاره یو ښه او ګټور کاروبار برابر کړی ؤ.', 'هلته د دیمیتریوس په نوم یو زرګر و چې د ارتیمیسې د بت د عبادت جای د سپینو زرو نمونې به یې جورولې او په دې دول یې د کسبګرو دپاره یو شه او ګتور کاروبار برابر کری و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24869, 'Acts 19:25', 'Acts', 19, 25, 'نو دیمیتریوس هغوی او د هغوی په شان نور کسبګر سره راټول کړل او ورته یې وویل: «ای ملګرو، تاسو پوهېږئ چې مونږ له همدې کاروبار څخه ښه ګټه تر‌لاسه کوو.', 'نو دیمیتریوس هغوی او د هغوی په شان نور کسبګر سره راتول کرل او ورته یې وویل: «ای ملګرو، تاسو پوهېزی چې مونز له همدې کاروبار چخه شه ګته تر‌لاسه کوو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24870, 'Acts 19:26', 'Acts', 19, 26, 'لکه څنګه چې تاسو وینئ او اورئ چې دې پولوس یوازې په افسیس کې نه، بلکې د اسیا په ټول ولایت کې ګڼ شمېر خلک په خپلو خبرو ځان ته را‌اړولي او بې‌لارې کړي دي. هغه وایي چې د انسان په لاس جوړ شوي خدایان بالکل خدایان نه دي.', 'لکه چنګه چې تاسو وینی او اوری چې دې پولوس یوازې په افسیس کې نه، بلکې د اسیا په تول ولایت کې ګن شمېر خلک په خپلو خبرو جان ته را‌ارولی او بې‌لارې کری دی. هغه وایی چې د انسان په لاس جور شوی خدایان بالکل خدایان نه دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(24871, 'Acts 19:27', 'Acts', 19, 27, 'نو دا خطر شته چې نه یوازې دا چې زمونږ کاروبار به بدنام شي بلکې د دې خطر هم شته چې زمونږ د لوی خدای ارتیمیسې د عبادت ځای به هم بې‌اعتباره شي او د هغې شان او شوکت چې په اسیا او ټوله نړۍ کې ورته عبادت کیږي، هم له منځه لاړ شي.»', 'نو دا خطر شته چې نه یوازې دا چې زمونز کاروبار به بدنام شی بلکې د دې خطر هم شته چې زمونز د لوی خدای ارتیمیسې د عبادت جای به هم بې‌اعتباره شی او د هغې شان او شوکت چې په اسیا او توله نری کې ورته عبادت کیزی، هم له منجه لار شی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24872, 'Acts 19:28', 'Acts', 19, 28, 'کله چې هغوی دا خبرې واورېدلې، نو ډېر په قهر شول او چیغې یې ووهلې: «لویه ده د افسیسیانو ارتیمیسه!»', 'کله چې هغوی دا خبرې واورېدلې، نو دېر په قهر شول او چیغې یې ووهلې: «لویه ده د افسیسیانو ارتیمیسه!»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24873, 'Acts 19:29', 'Acts', 19, 29, 'په ټول ښار کې شور او غوغا پیدا شوه. خلکو ګایوس او ارسترخوس چې د مقدونیې څخه وو او د پولوس د سفر ملګري وو، ونیول او په راښکلو راښکلو یې د ښار د غونډې ځای ته یووړل.', 'په تول شار کې شور او غوغا پیدا شوه. خلکو ګایوس او ارسترخوس چې د مقدونیې چخه وو او د پولوس د سفر ملګری وو، ونیول او په راشکلو راشکلو یې د شار د غوندې جای ته یوورل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24874, 'Acts 19:30', 'Acts', 19, 30, 'پولوس غوښتل چې دننه ورشي او د خلکو سره خبرې وکړي، خو ایماندارانو هغه پرېنښود.', 'پولوس غوشتل چې دننه ورشی او د خلکو سره خبرې وکری، خو ایماندارانو هغه پرېنشود.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24875, 'Acts 19:31', 'Acts', 19, 31, 'د ولایت ځینو واکمنانو چې د پولوس ملګري وو هم هغه ته پیغام ورولېږه او هغه ته یې زاري وکړه چې د غونډې ځای ته لاړ نه شي.', 'د ولایت جینو واکمنانو چې د پولوس ملګری وو هم هغه ته پیغام ورولېزه او هغه ته یې زاری وکره چې د غوندې جای ته لار نه شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(24876, 'Acts 19:32', 'Acts', 19, 32, 'په دې وخت کې غونډه ګډه وډه شوه او ځینو به په چیغو چیغو کې یو څه او ځینو به بل څه ویل، ځکه چې په هغوی کې ډېر خلک په دې هم نه پوهېدل چې د څه دپاره دلته راټول شوي دي.', 'په دې وخت کې غونده ګده وده شوه او جینو به په چیغو چیغو کې یو چه او جینو به بل چه ویل، جکه چې په هغوی کې دېر خلک په دې هم نه پوهېدل چې د چه دپاره دلته راتول شوی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_32.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(24877, 'Acts 19:33', 'Acts', 19, 33, 'ځینو یهودي مشرانو د سکندر په نوم سړی د خلکو د ګڼې ګوڼې مخې ته ورټېله کړ او هغه ته یې وویل چې یو‌څه باید ووایي. هغه په خپل لاس اشاره وکړه چې خلک غلي شي او کوښښ یې وکړ چې هر هغه څه چې شوي وو، هغه بیان کړي.', 'جینو یهودی مشرانو د سکندر په نوم سری د خلکو د ګنې ګونې مخې ته ورتېله کر او هغه ته یې وویل چې یو‌چه باید ووایی. هغه په خپل لاس اشاره وکره چې خلک غلی شی او کوشش یې وکر چې هر هغه چه چې شوی وو، هغه بیان کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_33.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(24878, 'Acts 19:34', 'Acts', 19, 34, 'خو کله چې خلک پوه شول چې سکندر یهودي دی، نو ټولو په یو اواز دوه ساعته چیغې ووهلې: «لویه ده د افسیسیانو خدای ارتیمیسه!»', 'خو کله چې خلک پوه شول چې سکندر یهودی دی، نو تولو په یو اواز دوه ساعته چیغې ووهلې: «لویه ده د افسیسیانو خدای ارتیمیسه!»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_34.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(24879, 'Acts 19:35', 'Acts', 19, 35, 'په پای کې ښاروال خلک غلي کړل او ویې ویل: «ای د افسیس خلکو، ټولو ته معلومه ده چې د افسیس ښار د لویې ارتیمیسې د عبادتځای او د هغې سپېڅلې تیږې ساتونکی دی چې د اسمان څخه راغورځېدلې ده.', 'په پای کې شاروال خلک غلی کرل او ویې ویل: «ای د افسیس خلکو، تولو ته معلومه ده چې د افسیس شار د لویې ارتیمیسې د عبادتجای او د هغې سپېچلې تیزې ساتونکی دی چې د اسمان چخه راغورجېدلې ده.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Acts_19_35.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
